(() => {
  const root = document.getElementById('djMode');
  const padAnimals=[['Cachorro','🐶','dog'],['Gato','🐱','cat'],['Vaca','🐮','cow'],['Pato','🦆','geese'],['Passarinho','🐤','bird'],['Coruja','🦉','owl'],['Leão','🦁','lion'],['Sapo','🐸','fantasy'],['Elefante','🐘','fantasy'],['Coelhinho','🐰','fantasy'],['Cavalo','🐴','fantasy'],['Golfinho','🐬','ocean'],['Pintinho','🐥','bird'],['Macaco','🐵','fantasy'],['Urso','🐻','fantasy'],['Lobo','🐺','fantasy']];
  const colors=['#ff858e','#ffc875','#fff18a','#8af0bd','#81dcff','#b8a0ff','#ffa6d6','#75eddf'];
  const keys='asdfghjkqwertyui';
  const deck=(side,title,animal)=>`<section class="deck ${side}"><h2>${title}</h2><button class="jog" data-side="${side}" aria-label="Jog ${title}: scratch de DJ"><span>${animal}</span></button><div class="pads">${Array.from({length:8},(_,i)=>{const a=padAnimals[i+(side==='right'?8:0)];return `<button class="pad" data-pad="${i+(side==='right'?8:0)}" style="--pad:${colors[i]}" aria-label="${title} ${a[0]}">${a[1]}<small>${a[0]} · ${keys[i+(side==='right'?8:0)].toUpperCase()}</small></button>`}).join('')}</div></section>`;
  root.innerHTML=`<header class="dj-header"><h1>🎧 DJ Bela</h1><p>Pequenas mãos, grandes batidas · 128 BPM</p></header><button class="dj-close" aria-label="Fechar mesa DJ">×</button><div class="dj-console">${deck('left','Bichinhos do campo','🐶')}<section class="mixer"><div class="beat-light"></div><div class="fx"><button data-fx="0">🚀 Uau!</button><button data-fx="1">💫 Brilho</button><button data-fx="2">💧 Bolhas</button><button data-fx="3">🌪️ Vento</button></div><label>Mistura dos bichinhos<input id="crossfader" aria-label="Crossfader" type="range" min="0" max="100" value="50"></label><label>Volume da música<input id="djVolume" aria-label="Volume da música" type="range" min="0" max="100" value="45"></label></section>${deck('right','Bichinhos da floresta','🦁')}</div><p class="dj-status" aria-live="polite">Gire os bichinhos e toque nos quadradinhos!</p><p class="dj-help">Arraste os discos • misture no fader • aperte várias cores</p>`;
  let ctx,master,music,active=false,timer,nextBeat=0,beat=0,mix=.5,lastFader=0;
  const samples=new Set(), oscillators=new Set();
  function audio(){if(!ctx){ctx=new AudioContext();master=ctx.createGain();master.gain.value=.4;master.connect(ctx.destination);music=ctx.createGain();music.gain.value=.45;music.connect(master)}if(ctx.state!=='running')ctx.resume();}
  function note(freq,duration=.15,shape='sine',when=0,end=freq,level=.2,bus=master){if(!ctx)return;const t=ctx.currentTime+when,o=ctx.createOscillator(),g=ctx.createGain();o.type=shape;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(30,end),t+duration);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(level,t+.005);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g).connect(bus);o.start(t);o.stop(t+duration+.02);oscillators.add(o);o.onended=()=>oscillators.delete(o);}
  function hiss(duration=.1,when=0,level=.1,bus=master){const b=ctx.createBuffer(1,ctx.sampleRate*duration,ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,3);const src=ctx.createBufferSource(),g=ctx.createGain();src.buffer=b;g.gain.value=level;src.connect(g).connect(bus);src.start(ctx.currentTime+when);oscillators.add(src);src.onended=()=>oscillators.delete(src);}
  function pad(index){if(!active)return;audio();const animal=padAnimals[index];const file=animal[2];const a=new Audio(`./sounds/${file}.mp3`);a.volume=.58;a.play().catch(()=>{const base=180+index*38;note(base,.24,'triangle',0,base*.55,.32);if(index%3===1)hiss(.12,0,.15)});setTimeout(()=>a.pause(),1200);const button=root.querySelector(`[data-pad="${index}"]`);button.classList.add('hit');setTimeout(()=>button.classList.remove('hit'),120);status(`${animal[1]} ${animal[0]}!`);}
  function status(text){root.querySelector('.dj-status').textContent=text;}
  function fx(i){if(!active)return;audio();if(i===0)note(180,.5,'triangle',0,1100,.22);if(i===1)[1047,1568,2093].forEach((f,n)=>note(f,.3,'sine',n*.09));if(i===2)[0,.09,.18].forEach(t=>note(800,.09,'sine',t,130,.3));if(i===3)hiss(.7,0,.22);status(['Uau! 🚀','Brilho! 💫','Plop, plop! 💧','Fuuu! 🌪️'][i]);}
  const animals={left:[['dog','🐶'],['cat','🐱'],['cow','🐮'],['geese','🦆']],right:[['lion','🦁'],['bird','🐤'],['owl','🦉']]};let counts={left:0,right:0};
  function jog(side,rate=1){if(!active)return;audio();const duration=.12+.14*Math.min(1.6,Math.abs(rate));hiss(duration,0,.28);note(rate<0?95:165,duration,'sawtooth',0,rate<0?55:420,.12);note(rate<0?180:280,duration*.6,'triangle',.015,rate<0?90:650,.08);const disc=root.querySelector(`[data-side="${side}"] .jog`);disc.classList.add('scratch');setTimeout(()=>disc.classList.remove('scratch'),180);status('Scratch! 🎚️');}
  function scheduler(){if(!active)return;while(nextBeat<ctx.currentTime+.12){const t=Math.max(0,nextBeat-ctx.currentTime);note(130,.2,'sine',t,42,.4,music);hiss(.04,t,.05,music);hiss(.035,t+60/128/2,.04,music);if(beat%2===1)hiss(.13,t,.13,music);const bass=[130.81,130.81,164.81,146.83,110,110,146.83,123.47][beat%8];note(bass,.28,'triangle',t,bass,.11,music);if(beat%2===0)note(bass*4,.3,'sine',t,bass*4,.06,music);nextBeat+=60/128;beat++;}root.querySelector('.beat-light').classList.toggle('pulse',Math.floor(ctx.currentTime/(60/128))%2===0);}
  function start(){audio();active=true;nextBeat=ctx.currentTime;beat=0;clearInterval(timer);scheduler();timer=setInterval(scheduler,25);}
  function stop(){active=false;clearInterval(timer);for(const a of samples)a.pause();samples.clear();for(const o of oscillators){try{o.stop()}catch{}}oscillators.clear();}
  root.querySelectorAll('.pad').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();pad(Number(b.dataset.pad))}));
  root.querySelectorAll('[data-fx]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();fx(Number(b.dataset.fx))}));
  root.querySelectorAll('.jog').forEach(b=>{let pointer=null,last=0,angle=0;b.addEventListener('pointerdown',e=>{e.preventDefault();pointer=e.pointerId;b.setPointerCapture(pointer);last=performance.now();jog(b.dataset.side)});b.addEventListener('pointermove',e=>{if(pointer!==e.pointerId)return;angle+=e.movementX||5;b.style.transform=`rotate(${angle}deg)`;if(performance.now()-last>130){last=performance.now();jog(b.dataset.side,e.movementX<0?.75:1.25)}});['pointerup','pointercancel','lostpointercapture'].forEach(type=>b.addEventListener(type,()=>pointer=null));});
  function faderSound(){if(performance.now()-lastFader>70){lastFader=performance.now();note(250+mix*800,.07,'sine',0,500,.1)}}
  root.querySelector('#crossfader').addEventListener('input',e=>{mix=e.target.value/100;faderSound();status('Misturando os bichinhos!')});
  root.querySelector('#djVolume').addEventListener('input',e=>{music.gain.value=e.target.value/100;faderSound()});
  root.querySelector('.dj-close').addEventListener('click',e=>{stop();window.belaClose(e)});
  window.addEventListener('pagehide',stop);
  window.belaDJ={start,stop,key:e=>{const k=String(e.key).toLowerCase();if(k==='z')jog('left');else if(k==='x')jog('right');else {const i=keys.indexOf(k);pad(i<0?Math.abs((e.code||'').length)%16:i)}}};
})();
